package com.cpf.core.common.runtimecontrol.applier;import com.cpf.core.api.runtimecontrol.*;import com.cpf.core.common.attachment.CpfAttachmentRuntimePolicy;import java.util.*;
public final class CpfAttachmentPolicyRuntimeApplier implements CpfRuntimeChangeApplier{private final CpfAttachmentRuntimePolicy p;public CpfAttachmentPolicyRuntimeApplier(CpfAttachmentRuntimePolicy p){this.p=p;}public String changeType(){return "ATTACHMENT_POLICY";}public boolean supportsIdempotentReplay(){return true;}public boolean snapshotCapable(){return true;}public CpfRuntimeApplyResult apply(CpfRuntimeDelivery d){try{p.replaceAttachment(d.desiredVersion(),num(d.payload().get("maxBytes"),10485760),set(d.payload().get("allowedExtensions")),set(d.payload().get("allowedMimeTypes")),bool(d.payload().get("scanRequired"),false),num(d.payload().get("retentionDays"),3650),bool(d.payload().get("quarantineOnFailure"),true),bool(d.payload().get("watermarkOnStore"),false));return CpfRuntimeApplyResult.success(d.payloadHash());}catch(RuntimeException e){return CpfRuntimeApplyResult.failure("ATTACHMENT_POLICY_INVALID","Attachment policy payload 오류");}}private long num(Object v,long f){return v instanceof Number n?n.longValue():v==null?f:Long.parseLong(String.valueOf(v));}private boolean bool(Object v,boolean f){return v instanceof Boolean b?b:v==null?f:Boolean.parseBoolean(String.valueOf(v));}private Set<String>set(Object v){if(!(v instanceof List<?>l))return Set.of();LinkedHashSet<String>s=new LinkedHashSet<>();for(Object x:l)if(x!=null)s.add(String.valueOf(x));return Set.copyOf(s);}}
